def main_count(mode):
    return (1 if mode.endswith('_L') else 2) if mode.startswith('standard') else (0 if mode.endswith('_L') else 1)

def travel(age,mode,key,route,cap=None):
    d=copy.deepcopy(prior['travel_routes'][ROUTES[route]]['age_prescriptions'][age][mode][key])
    if key=='E1' and cap is not None:d['sets']=min(d['sets'],cap)
    if not d['sets']:return d
    if route=='long_purposeful' and key=='E1':
        d['variant']='Progressive Build and Upright Rhythm Run — modest nonmaximal intent context'
        d['effort_load']='Bodyweight. From still comfortable standing, build smoothly over0–10m from about2/10 toward4/10, then keep relaxed purposeful4/10 through10–20m. Slow gradually through20–35m. This is a provisional coaching effort cue, not a speed percentage, required pace or maximal/flying sprint.'
        d['running_intent']='modest_nonmaximal_teaching'
        d['execution_segments'][1]['name']='ten_metre_relaxed_purposeful_rhythm'
    if route in ('long_purposeful','long_easy') and key=='E1':
        d['planned_build_effort_0_10']=[2,4] if route=='long_purposeful' else [2,3]
        d['planned_rhythm_effort_0_10']=4 if route=='long_purposeful' else 3
        d['segment_seconds_are_required_pace']=False
        d['notes']+=' Retain the actual smaller compatible opportunity count. All25s active phases are planning allowances, not segment targets; earlier clearance leaves quiet time. The full40s outside return includes turning/rejoining. Longer actual action/return delays later releases; omit uncompleted later work instead of forcing pace. Record actual effort, slowing and faults; no extra trial.'
    return d

