    v['main_count_caps']={'1':{a:{m:travel(a,m,'E1',r,1) for m in MODES} for a in AGES}}
    v['modest_entry_policy']={'first_increase_requires_actual_repeatable_easy_long_run':True,'retention_requires_actual_repeatable_same_route_modest_run':True,'retention_requires_reconstructed_older_easy_record':False,'current_response_and_runoff_fit_required_for_both':True,'actual_selected_basis':None} if r=='long_purposeful' else None
    v['requires_prior_successful_purposeful_run']=False
    v['requires_current_runoff_suitability_for_selected_intent']=r in ('long_purposeful','long_easy','short_acc')
    v['P2_or_E0_alone_grants_running_readiness']=False
