def rep_cap(d,c):
    d=copy.deepcopy(d)
    if d['sets']:d['repetitions_per_set']=min(d['repetitions_per_set'],c)
    d['notes']+=' Preserve the smaller actual recent count; this ceiling never restores missed repetitions. Setup, handling, tempo, effort and recovery remain unchanged.'
    return d

